  ('Polycarbonate Sheet - 3mm - 1/2in Grid Pattern - 47in x 23in', 'REV-21-3410', 'REV Polycarbonate Sheets are lightweight, clear, and impact-resistant plastic sheets for robot construction, prototyping, covers, guards, sponsor panels, intake surfaces, funnels, and other custom mechanisms. Polycarbonate is durable while still allowing visibility of game pieces, electronics, and internal robot components. The 1mm Polycarbonate Sheet 5 Pack (REV-41-3049-PK5) includes five smaller, more manageable 400mm x 350mm sheets that are easy to store, handle, and modify. This thin and…', 'REV Robotics', null, true, 'https://www.revrobotics.com/Polycarbonate-Sheets/?sku=REV-21-3410', 'https://cdn11.bigcommerce.com/s-t3eo8vwp22/products/972/images/3846/REV-41-7357_PolycardGrid_Family_Edited-Final__84564.1782404846.500.500.png?c=2', 'Competition / FIRST Tech Challenge / REV DUO FTC Starter Bot', 'rev'),
  ('3/8in Nut Strip - 3 Pos - 2 Pack', 'REV-21-3420-PK2', '3/8 Nut Strips are compatible with the REV ION System featuring convenient 1/2in spaced #10-32 threaded holes that are inline with each other allowing easy fastening of aligned plates and structure without the need for individual nuts. Specifications Material: 6061 Aluminum Finish: Black Anodized Thread Pitch: #10-32 Width: 0.375in (9.53mm) Height: 0.375in (9.53mm) Length: 3/8 Nut Strip - 3 Pos: 1.5in (37.59mm) 3/8 Nut Strip - 5 Pos: 2.5in (62.99mm) 3/8 Nut Strip - 7 Pos: 3.5in (88.39mm) 3/8…', 'REV Robotics', null, true, 'https://www.revrobotics.com/3-8in-nut-strips/?sku=REV-21-3420-PK2', 'https://cdn11.bigcommerce.com/s-t3eo8vwp22/products/821/images/3590/3-8nutstrip_FAMILY_FINAL__50961.1760542325.500.500.png?c=2', 'REV ION / REV ION FRC Starter Bot / Drivetrain', 'rev'),
  ('3/8in Nut Strip - 5 Pos - 2 Pack', 'REV-21-3422-PK2', '3/8 Nut Strips are compatible with the REV ION System featuring convenient 1/2in spaced #10-32 threaded holes that are inline with each other allowing easy fastening of aligned plates and structure without the need for individual nuts. Specifications Material: 6061 Aluminum Finish: Black Anodized Thread Pitch: #10-32 Width: 0.375in (9.53mm) Height: 0.375in (9.53mm) Length: 3/8 Nut Strip - 3 Pos: 1.5in (37.59mm) 3/8 Nut Strip - 5 Pos: 2.5in (62.99mm) 3/8 Nut Strip - 7 Pos: 3.5in (88.39mm) 3/8…', 'REV Robotics', null, true, 'https://www.revrobotics.com/3-8in-nut-strips/?sku=REV-21-3422-PK2', 'https://cdn11.bigcommerce.com/s-t3eo8vwp22/products/821/images/3590/3-8nutstrip_FAMILY_FINAL__50961.1760542325.500.500.png?c=2', 'REV ION / REV ION FRC Starter Bot / Drivetrain', 'rev'),
